// TestMapAttachment_HappyPath verifies all fields are set in the metadata frame.
func TestMapAttachment_HappyPath(t *testing.T) {
	a := legacy.LegacyAttachment{
		LegacyID:        "att-001",
		MessageLegacyID: "msg-001",
		Filename:        "invoice.pdf",
		MIMEType:        "application/pdf",
		FilesystemPath:  "/data/att-001.pdf",
	}
	result, err := mapper.MapAttachment(a)
	require.NoError(t, err)
	require.Empty(t, result.Notes)
	frame := result.MetadataFrame
	assert.Equal(t, "att-001", frame.LegacyId)
	assert.Equal(t, "msg-001", frame.MessageLegacyId)
	assert.Equal(t, "invoice.pdf", frame.Filename)
	assert.Equal(t, "application/pdf", frame.MimeType)
}

// TestMapAttachment_MissingMessageIDReturnsError.
