	a := legacy.LegacyAttachment{
		LegacyID:        "att-002",
		MessageLegacyID: "",
		Filename:        "photo.jpg",
	}
	_, err := mapper.MapAttachment(a)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "message_legacy_id is required")
}

// TestMapAttachment_MissingFilenameReturnsError.
func TestMapAttachment_MissingFilenameReturnsError(t *testing.T) {
