// TestMapAttachment_SetsLegacyID verifies legacy_id is always set.
func TestMapAttachment_SetsLegacyID(t *testing.T) {
	a := legacy.LegacyAttachment{
		LegacyID:        "att-leg-007",
		MessageLegacyID: "msg-001",
		Filename:        "doc.txt",
	}
	result, err := mapper.MapAttachment(a)
	require.NoError(t, err)
	assert.Equal(t, "att-leg-007", result.MetadataFrame.LegacyId)
}


