package mapper

import (
	"encoding/json"
	"fmt"

	"google.golang.org/protobuf/types/known/structpb"

	channelv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/channel/v1"
	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyTypeToProto maps legacy channel type strings to the proto enum.
// Types not listed here are mapped to CHANNEL_TYPE_UNSPECIFIED; the
// Python handler will force-downgrade them to
// CHANNEL_STATUS_UNSUPPORTED_IN_THIS_VERSION.
var legacyTypeToProto = map[string]channelv1.ChannelType{
	"email":            channelv1.ChannelType_CHANNEL_TYPE_EMAIL,
	"telegram_bot":     channelv1.ChannelType_CHANNEL_TYPE_TELEGRAM_BOT,
	"telegram_client":  channelv1.ChannelType_CHANNEL_TYPE_TELEGRAM_CLIENT,
	"twilio_sms":       channelv1.ChannelType_CHANNEL_TYPE_TWILIO_SMS,
	"android_sms":      channelv1.ChannelType_CHANNEL_TYPE_ANDROID_SMS,
	"whatsapp":         channelv1.ChannelType_CHANNEL_TYPE_WHATSAPP,
	"signal":           channelv1.ChannelType_CHANNEL_TYPE_SIGNAL,
	"social_x":         channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_X,
	"social_facebook":  channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_FACEBOOK,
	"social_instagram": channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_INSTAGRAM,
	"range_exercise":   channelv1.ChannelType_CHANNEL_TYPE_RANGE_EXERCISE,
}

// MapChannelResult carries the mapped request and any rejection notes.
type MapChannelResult struct {
	Request *ingestv1.MigrateChannelRequest
	// Notes collects soft warnings (e.g. unknown type downgraded).
	Notes []RejectionNote
}

// RejectionNote is a soft mapper-level warning attached to a result.
type RejectionNote struct {
	LegacyID string
	Reason   string
	Severity string // "warn" or "error"
}

// SeverityWarn / SeverityError mirror the rejection package constants
// so mapper callers don't need to import both packages.
const (
	SeverityWarn  = "warn"
	SeverityError = "error"
)

// MapChannel translates a LegacyChannel into a MigrateChannelRequest.
//
// Rules:
//   - Legacy type string is looked up in legacyTypeToProto; unknown types
//     map to CHANNEL_TYPE_UNSPECIFIED with a SeverityWarn note. The Python
//     handler will force-downgrade to UNSUPPORTED_IN_THIS_VERSION.
//   - Legacy config JSON is parsed into a structpb.Struct; malformed JSON
//     yields a SeverityWarn note and an empty Struct.
//   - legacy_id is always set for idempotency.
func MapChannel(ch legacy.LegacyChannel) (MapChannelResult, error) {
	protoType, known := legacyTypeToProto[ch.Type]
	var notes []RejectionNote
	if !known {
		notes = append(notes, RejectionNote{
			LegacyID: ch.LegacyID,
			Reason:   fmt.Sprintf("unknown channel type %q mapped to UNSPECIFIED (server will force-downgrade to UNSUPPORTED_IN_THIS_VERSION)", ch.Type),
			Severity: SeverityWarn,
		})
		protoType = channelv1.ChannelType_CHANNEL_TYPE_UNSPECIFIED
	}

	// Parse legacy JSON config into structpb.Struct.
	var cfgStruct *structpb.Struct
	if len(ch.Config) > 0 && string(ch.Config) != "{}" {
		var raw map[string]interface{}
		if err := json.Unmarshal(ch.Config, &raw); err != nil {
			notes = append(notes, RejectionNote{
				LegacyID: ch.LegacyID,
				Reason:   fmt.Sprintf("malformed config JSON: %v; using empty struct", err),
				Severity: SeverityWarn,
			})
			cfgStruct = &structpb.Struct{}
		} else {
			var pbErr error
			cfgStruct, pbErr = structpb.NewStruct(raw)
			if pbErr != nil {
				notes = append(notes, RejectionNote{
					LegacyID: ch.LegacyID,
					Reason:   fmt.Sprintf("config to structpb failed: %v; using empty struct", pbErr),
					Severity: SeverityWarn,
				})
				cfgStruct = &structpb.Struct{}
			}
		}
	} else {
		cfgStruct = &structpb.Struct{}
	}

	req := &ingestv1.MigrateChannelRequest{
		LegacyId:          ch.LegacyID,
		OrgId:             ch.OrgID,
		Name:              ch.Name,
		Type:              protoType,
		Config:            cfgStruct,
		IsDefault:         ch.IsDefault,
		OwnerLegacyUserId: ch.OwnerUserID,
	}

	return MapChannelResult{Request: req, Notes: notes}, nil
}


