package mapper_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	channelv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/channel/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/mapper"
)

// TestMapChannel_KnownTypes is a table-driven test verifying that all
// known legacy type strings map to the correct proto enum value (A.1.3 gate).
func TestMapChannel_KnownTypes(t *testing.T) {
	tests := []struct {
		legacyType string
		want       channelv1.ChannelType
	}{
		{"email", channelv1.ChannelType_CHANNEL_TYPE_EMAIL},
		{"telegram_bot", channelv1.ChannelType_CHANNEL_TYPE_TELEGRAM_BOT},
		{"telegram_client", channelv1.ChannelType_CHANNEL_TYPE_TELEGRAM_CLIENT},
		{"twilio_sms", channelv1.ChannelType_CHANNEL_TYPE_TWILIO_SMS},
		{"android_sms", channelv1.ChannelType_CHANNEL_TYPE_ANDROID_SMS},
		{"whatsapp", channelv1.ChannelType_CHANNEL_TYPE_WHATSAPP},
		{"signal", channelv1.ChannelType_CHANNEL_TYPE_SIGNAL},
		{"social_x", channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_X},
		{"social_facebook", channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_FACEBOOK},
		{"social_instagram", channelv1.ChannelType_CHANNEL_TYPE_SOCIAL_INSTAGRAM},
		{"range_exercise", channelv1.ChannelType_CHANNEL_TYPE_RANGE_EXERCISE},
	}
	for _, tc := range tests {
		t.Run(tc.legacyType, func(t *testing.T) {
			ch := legacy.LegacyChannel{
				LegacyID: "chan-" + tc.legacyType,
				OrgID:    "org-001",
				Type:     tc.legacyType,
				Name:     "Test Channel",
				Config:   []byte(`{}`),
			}
			result, err := mapper.MapChannel(ch)
			require.NoError(t, err)
			assert.Equal(t, tc.want, result.Request.Type)
			assert.Empty(t, result.Notes, "known types should produce no warnings")
			assert.Equal(t, "chan-"+tc.legacyType, result.Request.LegacyId)
		})
	}
}

// TestMapChannel_UnknownTypeProducesWarnNote verifies that an unknown
// type maps to UNSPECIFIED with a SeverityWarn note.
func TestMapChannel_UnknownTypeProducesWarnNote(t *testing.T) {
	ch := legacy.LegacyChannel{
		LegacyID: "chan-unknown",
		OrgID:    "org-001",
		Type:     "jabber",
		Name:     "Jabber Channel",
		Config:   []byte(`{}`),
	}
	result, err := mapper.MapChannel(ch)
	require.NoError(t, err)
	assert.Equal(t, channelv1.ChannelType_CHANNEL_TYPE_UNSPECIFIED, result.Request.Type)
	require.Len(t, result.Notes, 1)
	assert.Equal(t, mapper.SeverityWarn, result.Notes[0].Severity)
	assert.Contains(t, result.Notes[0].Reason, "jabber")
}

// TestMapChannel_MalformedConfigJSON verifies that malformed JSON config
// is replaced by an empty struct and a warn note is returned.
func TestMapChannel_MalformedConfigJSON(t *testing.T) {
	ch := legacy.LegacyChannel{
		LegacyID: "chan-bad-config",
		OrgID:    "org-001",
		Type:     "email",
		Name:     "Email",
		Config:   []byte(`not valid json`),
	}
	result, err := mapper.MapChannel(ch)
	require.NoError(t, err)
	// Should still return a request (soft failure).
	require.NotNil(t, result.Request)
	assert.Equal(t, channelv1.ChannelType_CHANNEL_TYPE_EMAIL, result.Request.Type)
	require.Len(t, result.Notes, 1)
	assert.Equal(t, mapper.SeverityWarn, result.Notes[0].Severity)
	assert.Contains(t, result.Notes[0].Reason, "malformed config JSON")
}

// TestMapChannel_SetsAllFields verifies that all request fields are
// populated correctly from the legacy DTO.
func TestMapChannel_SetsAllFields(t *testing.T) {
	ch := legacy.LegacyChannel{
		LegacyID:    "chan-001",
		OrgID:       "org-abc",
		Type:        "email",
		Name:        "Primary Email",
		OwnerUserID: "user-001",
		Config:      []byte(`{"smtp_host":"smtp.example.com"}`),
		IsDefault:   true,
	}
	result, err := mapper.MapChannel(ch)
	require.NoError(t, err)
	req := result.Request
	assert.Equal(t, "chan-001", req.LegacyId)
	assert.Equal(t, "org-abc", req.OrgId)
	assert.Equal(t, "Primary Email", req.Name)
	assert.Equal(t, channelv1.ChannelType_CHANNEL_TYPE_EMAIL, req.Type)
	assert.True(t, req.IsDefault)
	assert.Equal(t, "user-001", req.OwnerLegacyUserId)
	assert.NotNil(t, req.Config)
	// Verify the config struct has the smtp_host field.
	fields := req.Config.GetFields()
	require.NotNil(t, fields["smtp_host"])
	assert.Equal(t, "smtp.example.com", fields["smtp_host"].GetStringValue())
}


