package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/timestamppb"

	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	messagev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/message/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyMsgDirectionToProto maps legacy direction strings to the proto enum.
var legacyMsgDirectionToProto = map[string]messagev1.MessageDirection{
	"inbound":  messagev1.MessageDirection_MESSAGE_DIRECTION_INBOUND,
	"outbound": messagev1.MessageDirection_MESSAGE_DIRECTION_OUTBOUND,
}

// legacyMsgStatusToProto maps terminal legacy status strings to the proto enum.
var legacyMsgStatusToProto = map[string]messagev1.MessageStatus{
	"sent":     messagev1.MessageStatus_MESSAGE_STATUS_SENT,
	"received": messagev1.MessageStatus_MESSAGE_STATUS_RECEIVED,
	// Legacy aliases.
	"delivered": messagev1.MessageStatus_MESSAGE_STATUS_DELIVERED,
	"failed":    messagev1.MessageStatus_MESSAGE_STATUS_FAILED,
}

// MapMessageResult carries the mapped request and any soft notes.
type MapMessageResult struct {
	Request *ingestv1.MigrateMessageRequest
	Notes   []RejectionNote
}

// MapMessage translates a LegacyMessage into a MigrateMessageRequest.
//
// Rules:
//   - conversation_legacy_id is required.
//   - body is required (may be empty string is allowed — legacy sms/attachments
//     may have no body).
//   - Unknown direction maps to INBOUND with a SeverityWarn note.
//   - Unknown status maps to RECEIVED (inbound) or SENT (outbound) with a note.
//   - legacy_id is always set for idempotency.
func MapMessage(msg legacy.LegacyMessage) (MapMessageResult, error) {
	if msg.ConversationLegacyID == "" {
		return MapMessageResult{}, fmt.Errorf("message %q: conversation_legacy_id is required", msg.LegacyID)
	}

	var notes []RejectionNote

	protoDir, knownDir := legacyMsgDirectionToProto[msg.Direction]
	if !knownDir {
		notes = append(notes, RejectionNote{
			LegacyID: msg.LegacyID,
			Reason:   fmt.Sprintf("unknown message direction %q mapped to INBOUND", msg.Direction),
			Severity: SeverityWarn,
		})
		protoDir = messagev1.MessageDirection_MESSAGE_DIRECTION_INBOUND
	}

	protoStatus, knownStatus := legacyMsgStatusToProto[msg.Status]
	if !knownStatus {
		defaultStatus := messagev1.MessageStatus_MESSAGE_STATUS_RECEIVED
		if protoDir == messagev1.MessageDirection_MESSAGE_DIRECTION_OUTBOUND {
			defaultStatus = messagev1.MessageStatus_MESSAGE_STATUS_SENT
		}
		if msg.Status != "" {
			notes = append(notes, RejectionNote{
				LegacyID: msg.LegacyID,
				Reason:   fmt.Sprintf("unknown message status %q mapped to default", msg.Status),
				Severity: SeverityWarn,
			})
		}
		protoStatus = defaultStatus
	}

	var sentAt *timestamppb.Timestamp
	if !msg.SentAt.IsZero() {
		sentAt = timestamppb.New(msg.SentAt)
	}
	var receivedAt *timestamppb.Timestamp
	if !msg.ReceivedAt.IsZero() {
		receivedAt = timestamppb.New(msg.ReceivedAt)
	}

	req := &ingestv1.MigrateMessageRequest{
		LegacyId:              msg.LegacyID,
		ConversationLegacyId:  msg.ConversationLegacyID,
		Direction:             protoDir,
		Status:                protoStatus,
		SenderLegacyUserId:    msg.SenderLegacyUserID,
		SenderContactLegacyId: msg.SenderContactLegacyID,
		Body:                  msg.Body,
		BodyHtml:              msg.BodyHTML,
		ExternalId:            msg.ExternalID,
		SentAt:                sentAt,
		ReceivedAt:            receivedAt,
	}

	return MapMessageResult{Request: req, Notes: notes}, nil
}


