// MapNote translates a LegacyNote into a MigrateNoteRequest.
//
// Rules:
//   - conversation_legacy_id is required.
//   - body is required (an empty analyst note would be useless).
//   - legacy_id is always set for idempotency.
func MapNote(n legacy.LegacyNote) (MapNoteResult, error) {
	if n.ConversationLegacyID == "" {
		return MapNoteResult{}, fmt.Errorf("note %q: conversation_legacy_id is required", n.LegacyID)
	}
	if n.Body == "" {
		return MapNoteResult{}, fmt.Errorf("note %q: body is required", n.LegacyID)
	}

	var createdAt *timestamppb.Timestamp
	if !n.CreatedAt.IsZero() {
		createdAt = timestamppb.New(n.CreatedAt)
	}

	req := &ingestv1.MigrateNoteRequest{
		LegacyId:             n.LegacyID,
		ConversationLegacyId: n.ConversationLegacyID,
		AuthorLegacyUserId:   n.AuthorLegacyUserID,
		Body:                 n.Body,
		CreatedAt:            createdAt,
	}

	return MapNoteResult{Request: req}, nil
}


