package mapper

import (
	"encoding/json"
	"fmt"

	"google.golang.org/protobuf/types/known/structpb"

	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	recipev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/recipe/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyRecipeTriggerTypeToProto maps legacy recipe trigger strings to the
// proto enum. Legacy triggers with no v2 equivalent (e.g. "missed_call") are
// intentionally absent and cause the recipe to be rejected.
var legacyRecipeTriggerTypeToProto = map[string]recipev1.TriggerType{
	"message_received":     recipev1.TriggerType_TRIGGER_TYPE_MESSAGE_RECEIVED,
	"keyword_detected":     recipev1.TriggerType_TRIGGER_TYPE_KEYWORD_DETECTED,
	"conversation_started": recipev1.TriggerType_TRIGGER_TYPE_CONVERSATION_STARTED,
	"contact_joined":       recipev1.TriggerType_TRIGGER_TYPE_CONTACT_JOINED,
	// "missed_call" intentionally absent -> rejected.
}

// legacyRecipeActionTypeToProto maps legacy recipe action strings to the proto enum.
var legacyRecipeActionTypeToProto = map[string]recipev1.ActionType{
	"send_message":           recipev1.ActionType_ACTION_TYPE_SEND_MESSAGE,
	"add_to_group":           recipev1.ActionType_ACTION_TYPE_ADD_TO_GROUP,
	"send_alert":             recipev1.ActionType_ACTION_TYPE_SEND_ALERT,
	"set_priority":           recipev1.ActionType_ACTION_TYPE_SET_PRIORITY,
	"add_note":               recipev1.ActionType_ACTION_TYPE_ADD_NOTE,
	"classify_message":       recipev1.ActionType_ACTION_TYPE_CLASSIFY_MESSAGE,
	"extract_entities":       recipev1.ActionType_ACTION_TYPE_EXTRACT_ENTITIES,
	"generate_response":      recipev1.ActionType_ACTION_TYPE_GENERATE_RESPONSE,
	"auto_tag":               recipev1.ActionType_ACTION_TYPE_AUTO_TAG,
	"sentiment_analysis":     recipev1.ActionType_ACTION_TYPE_SENTIMENT_ANALYSIS,
	"summarize_conversation": recipev1.ActionType_ACTION_TYPE_SUMMARIZE_CONVERSATION,
}

// MapRecipeResult carries the mapped request and any soft notes.
type MapRecipeResult struct {
	Request *ingestv1.MigrateRecipeRequest
	Notes   []RejectionNote
}

// MapRecipe translates a LegacyRecipe into a MigrateRecipeRequest.
//
// Rules:
//   - name is required.
//   - An unsupported trigger_type (e.g. "missed_call", absent from the proto
//     enum) returns an error with a SeverityError note.
//   - An unsupported action_type returns an error with a SeverityError note.
//   - trigger_config / action_config JSON is parsed into a structpb.Struct;
//     malformed JSON yields a SeverityWarn note and an empty Struct.
//   - legacy_id is always set for idempotency.
func MapRecipe(recipe legacy.LegacyRecipe) (MapRecipeResult, error) {
	if recipe.Name == "" {
		return MapRecipeResult{}, fmt.Errorf("recipe %q: name is required", recipe.LegacyID)
	}

	triggerType, ok := legacyRecipeTriggerTypeToProto[recipe.TriggerType]
	if !ok {
		note := RejectionNote{
			LegacyID: recipe.LegacyID,
			Reason:   fmt.Sprintf("unsupported trigger_type %q (missed_call has no v2 equivalent)", recipe.TriggerType),
			Severity: SeverityError,
		}
		return MapRecipeResult{Notes: []RejectionNote{note}}, fmt.Errorf("recipe %q: %s", recipe.LegacyID, note.Reason)
	}

	actionType, ok := legacyRecipeActionTypeToProto[recipe.ActionType]
	if !ok {
		note := RejectionNote{
			LegacyID: recipe.LegacyID,
			Reason:   fmt.Sprintf("unsupported action_type %q", recipe.ActionType),
			Severity: SeverityError,
		}
		return MapRecipeResult{Notes: []RejectionNote{note}}, fmt.Errorf("recipe %q: %s", recipe.LegacyID, note.Reason)
	}

	var notes []RejectionNote
	triggerConfig := parseRecipeConfig(recipe.LegacyID, "trigger_config", recipe.TriggerConfig, &notes)
	actionConfig := parseRecipeConfig(recipe.LegacyID, "action_config", recipe.ActionConfig, &notes)

	req := &ingestv1.MigrateRecipeRequest{
		LegacyId:                recipe.LegacyID,
		Name:                    recipe.Name,
		Description:             recipe.Description,
		IsActive:                recipe.IsActive,
		TriggerType:             triggerType,
		TriggerConfig:           triggerConfig,
		ActionType:              actionType,
		ActionConfig:            actionConfig,
		ChannelLegacyId:         recipe.ChannelLegacyID,
		ChannelType:             recipe.ChannelType,
		MaxExecutionsPerContact: int32(recipe.MaxExecutionsPerContact),
		CooldownMinutes:         int32(recipe.CooldownMinutes),
		CreatedByLegacyId:       recipe.CreatedByLegacyID,
	}

	return MapRecipeResult{Request: req, Notes: notes}, nil
}

// parseRecipeConfig parses raw JSON config bytes into a structpb.Struct.
// Empty/{} input yields an empty Struct; malformed JSON or a struct-build
// failure appends a SeverityWarn note and yields an empty Struct.
func parseRecipeConfig(legacyID, field string, raw []byte, notes *[]RejectionNote) *structpb.Struct {
	if len(raw) == 0 || string(raw) == "{}" {
		return &structpb.Struct{}
	}

	var m map[string]interface{}
	if err := json.Unmarshal(raw, &m); err != nil {
		*notes = append(*notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("malformed %s JSON: %v; using empty struct", field, err),
			Severity: SeverityWarn,
		})
		return &structpb.Struct{}
	}

	s, err := structpb.NewStruct(m)
	if err != nil {
		*notes = append(*notes, RejectionNote{
			LegacyID: legacyID,
			Reason:   fmt.Sprintf("%s to structpb failed: %v; using empty struct", field, err),
			Severity: SeverityWarn,
		})
		return &structpb.Struct{}
	}
	return s
}


