	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	templatev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/template/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyTmplCategoryToProto maps legacy template category strings to the proto enum.
var legacyTmplCategoryToProto = map[string]templatev1.TemplateCategory{
	"general":        templatev1.TemplateCategory_TEMPLATE_CATEGORY_GENERAL,
	"acknowledgment": templatev1.TemplateCategory_TEMPLATE_CATEGORY_ACKNOWLEDGMENT,
	"followup":       templatev1.TemplateCategory_TEMPLATE_CATEGORY_FOLLOWUP,
	"closure":        templatev1.TemplateCategory_TEMPLATE_CATEGORY_CLOSURE,
	"escalation":     templatev1.TemplateCategory_TEMPLATE_CATEGORY_ESCALATION,
	"information":    templatev1.TemplateCategory_TEMPLATE_CATEGORY_INFORMATION,
	"urgent":         templatev1.TemplateCategory_TEMPLATE_CATEGORY_URGENT,
	// Legacy aliases mapped to closest equivalent.
	"support": templatev1.TemplateCategory_TEMPLATE_CATEGORY_INFORMATION,
	"sales":   templatev1.TemplateCategory_TEMPLATE_CATEGORY_GENERAL,
}

// MapTemplateResult carries the mapped request and any soft notes.
type MapTemplateResult struct {
	Request *ingestv1.MigrateTemplateRequest
	Notes   []RejectionNote
}

// MapTemplate translates a LegacyTemplate into a MigrateTemplateRequest.
//
// Rules:
//   - name is required.
//   - content is required (may be empty only for degenerate legacy data).
//   - Unknown category maps to GENERAL with a SeverityWarn note.
//   - legacy_id is always set for idempotency.
func MapTemplate(tmpl legacy.LegacyTemplate) (MapTemplateResult, error) {
	if tmpl.Name == "" {
		return MapTemplateResult{}, fmt.Errorf("template %q: name is required", tmpl.LegacyID)
	}

	var notes []RejectionNote
	protoCategory, known := legacyTmplCategoryToProto[tmpl.Category]
	if !known && tmpl.Category != "" {
		notes = append(notes, RejectionNote{
			LegacyID: tmpl.LegacyID,
			Reason:   fmt.Sprintf("unknown template category %q mapped to GENERAL", tmpl.Category),
			Severity: SeverityWarn,
		})
		protoCategory = templatev1.TemplateCategory_TEMPLATE_CATEGORY_GENERAL
	}

	req := &ingestv1.MigrateTemplateRequest{
		LegacyId:          tmpl.LegacyID,
		Name:              tmpl.Name,
		Category:          protoCategory,
		Content:           tmpl.Content,
		CreatedByLegacyId: tmpl.CreatedByLegacyID,
	}

	return MapTemplateResult{Request: req, Notes: notes}, nil
}


