// MapAttachmentResult carries the metadata frame and any soft notes.
type MapAttachmentResult struct {
	// MetadataFrame is the first frame to send over the client-streaming RPC.
	// It carries legacy_id, message_legacy_id, filename, and mime_type.
	// Subsequent frames carry chunk bytes (built by the apply phase).
	MetadataFrame *ingestv1.MigrateAttachmentRequest
	Notes         []RejectionNote
}

// MapAttachment translates a LegacyAttachment into the metadata frame for the
// client-streaming MigrateAttachment RPC.
//
// Rules:
//   - message_legacy_id is required.
//   - filename is required.
//   - legacy_id is always set for idempotency.
func MapAttachment(a legacy.LegacyAttachment) (MapAttachmentResult, error) {
	if a.MessageLegacyID == "" {
		return MapAttachmentResult{}, fmt.Errorf("attachment %q: message_legacy_id is required", a.LegacyID)
	}
	if a.Filename == "" {
		return MapAttachmentResult{}, fmt.Errorf("attachment %q: filename is required", a.LegacyID)
	}

	frame := &ingestv1.MigrateAttachmentRequest{
		LegacyId:        a.LegacyID,
		MessageLegacyId: a.MessageLegacyID,
		Filename:        a.Filename,
		MimeType:        a.MIMEType,
	}

	return MapAttachmentResult{MetadataFrame: frame}, nil
}


