func MapContact(c legacy.LegacyContact) (MapContactResult, error) {
	if c.Identifier == "" {
		return MapContactResult{}, fmt.Errorf("contact %q: identifier is required", c.LegacyID)
	}

	var notes []RejectionNote

	var propsStruct *structpb.Struct
	if len(c.Properties) > 0 && string(c.Properties) != "{}" {
		var raw map[string]interface{}
		if err := json.Unmarshal(c.Properties, &raw); err != nil {
			notes = append(notes, RejectionNote{
				LegacyID: c.LegacyID,
				Reason:   fmt.Sprintf("malformed properties JSON: %v; using empty struct", err),
				Severity: SeverityWarn,
			})
			propsStruct = &structpb.Struct{}
		} else {
			var pbErr error
			propsStruct, pbErr = structpb.NewStruct(raw)
			if pbErr != nil {
				notes = append(notes, RejectionNote{
					LegacyID: c.LegacyID,
					Reason:   fmt.Sprintf("properties to structpb failed: %v; using empty struct", pbErr),
					Severity: SeverityWarn,
				})
				propsStruct = &structpb.Struct{}
			}
		}
	} else {
		propsStruct = &structpb.Struct{}
	}

	req := &ingestv1.MigrateContactRequest{
		LegacyId:        c.LegacyID,
		ChannelLegacyId: c.ChannelLegacyID,
		Identifier:      c.Identifier,
		DisplayName:     c.DisplayName,
		Properties:      propsStruct,
	}

	return MapContactResult{Request: req, Notes: notes}, nil
}


