// MapContactGroupResult carries the mapped request and any soft notes.
type MapContactGroupResult struct {
	Request *ingestv1.MigrateContactGroupRequest
	Notes   []RejectionNote
}

// MapContactGroup translates a LegacyContactGroup into a MigrateContactGroupRequest.
//
// Rules:
//   - name is required; an empty name returns an error.
//   - legacy_id is always set for idempotency.
//   - member contact_legacy_ids are forwarded as-is; the server resolves UUIDs.
func MapContactGroup(g legacy.LegacyContactGroup) (MapContactGroupResult, error) {
	if g.Name == "" {
		return MapContactGroupResult{}, fmt.Errorf("contact_group %q: name is required", g.LegacyID)
	}

	members := make([]*ingestv1.MigrateContactGroupMember, 0, len(g.Members))
	for _, m := range g.Members {
		members = append(members, &ingestv1.MigrateContactGroupMember{
			ContactLegacyId: m.ContactLegacyID,
		})
	}

	req := &ingestv1.MigrateContactGroupRequest{
		LegacyId:    g.LegacyID,
		Name:        g.Name,
		Description: g.Description,
		Color:       g.Color,
		Members:     members,
	}

	return MapContactGroupResult{Request: req}, nil
}


