package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/timestamppb"

	conversationv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/conversation/v1"
	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyConvStatusToProto maps legacy conversation status strings to the proto enum.
// The DB uses: active, archived, blocked.
var legacyConvStatusToProto = map[string]conversationv1.ConversationStatus{
	"active":   conversationv1.ConversationStatus_CONVERSATION_STATUS_ACTIVE,
	"archived": conversationv1.ConversationStatus_CONVERSATION_STATUS_ARCHIVED,
	"blocked":  conversationv1.ConversationStatus_CONVERSATION_STATUS_BLOCKED,
	// Legacy aliases: map old status names to nearest equivalent.
	"open":    conversationv1.ConversationStatus_CONVERSATION_STATUS_ACTIVE,
	"closed":  conversationv1.ConversationStatus_CONVERSATION_STATUS_ARCHIVED,
	"pending": conversationv1.ConversationStatus_CONVERSATION_STATUS_ACTIVE,
}

// MapConversationResult carries the mapped request and any soft notes.
type MapConversationResult struct {
	Request *ingestv1.MigrateConversationRequest
	Notes   []RejectionNote
}

// MapConversation translates a LegacyConversation into a MigrateConversationRequest.
//
// Rules:
//   - channel_legacy_id is required.
//   - For non-group conversations, contact_legacy_id is required.
//   - Unknown status values are mapped to ACTIVE with a SeverityWarn note.
//   - legacy_id is always set for idempotency.
func MapConversation(conv legacy.LegacyConversation) (MapConversationResult, error) {
	if conv.ChannelLegacyID == "" {
		return MapConversationResult{}, fmt.Errorf("conversation %q: channel_legacy_id is required", conv.LegacyID)
	}
	if !conv.IsGroup && conv.ContactLegacyID == "" {
		return MapConversationResult{}, fmt.Errorf("conversation %q: contact_legacy_id is required for non-group conversations", conv.LegacyID)
	}

	var notes []RejectionNote
	protoStatus, known := legacyConvStatusToProto[conv.Status]
	if !known && conv.Status != "" {
		notes = append(notes, RejectionNote{
			LegacyID: conv.LegacyID,
			Reason:   fmt.Sprintf("unknown conversation status %q mapped to ACTIVE", conv.Status),
			Severity: SeverityWarn,
		})
		protoStatus = conversationv1.ConversationStatus_CONVERSATION_STATUS_ACTIVE
	}

	var lastMsgAt *timestamppb.Timestamp
	if !conv.LastMessageAt.IsZero() {
		lastMsgAt = timestamppb.New(conv.LastMessageAt)
	}

	req := &ingestv1.MigrateConversationRequest{
		LegacyId:                    conv.LegacyID,
		ChannelLegacyId:             conv.ChannelLegacyID,
		IsGroup:                     conv.IsGroup,
		ContactLegacyId:             conv.ContactLegacyID,
		ExternalThreadId:            conv.ExternalThreadID,
		Title:                       conv.Title,
		Status:                      protoStatus,
		Priority:                    conv.Priority,
		LastMessageAt:               lastMsgAt,
		ParticipantContactLegacyIds: conv.ParticipantContactLegacyIDs,
	}

	return MapConversationResult{Request: req, Notes: notes}, nil
}


