package mapper

import (
	"fmt"

	chsharev1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/channel_share/v1"
	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// legacyVisibilityToProto maps legacy visibility strings to the proto enum.
var legacyVisibilityToProto = map[string]chsharev1.ShareVisibility{
	"private": chsharev1.ShareVisibility_SHARE_VISIBILITY_PRIVATE,
	"team":    chsharev1.ShareVisibility_SHARE_VISIBILITY_TEAM,
	"shared":  chsharev1.ShareVisibility_SHARE_VISIBILITY_SHARED,
	// Legacy aliases.
	"public": chsharev1.ShareVisibility_SHARE_VISIBILITY_TEAM, // downgrade public→team
}

// legacyRoleToProto maps legacy grant role strings to the proto enum.
var legacyRoleToProto = map[string]chsharev1.ShareRole{
	"viewer": chsharev1.ShareRole_SHARE_ROLE_VIEWER,
	"editor": chsharev1.ShareRole_SHARE_ROLE_EDITOR,
	"admin":  chsharev1.ShareRole_SHARE_ROLE_ADMIN,
}

// MapShareResult carries the mapped request and any soft notes.
type MapShareResult struct {
	Request *ingestv1.MigrateShareRequest
	Notes   []RejectionNote
}

// MapShare translates a LegacyShare into a MigrateShareRequest.
//
// Rules:
//   - channel_legacy_id is required.
//   - Unknown visibility maps to TEAM with a SeverityWarn note.
//   - Grants with unknown roles are mapped to VIEWER with a SeverityWarn note.
func MapShare(s legacy.LegacyShare) (MapShareResult, error) {
	if s.ChannelLegacyID == "" {
		return MapShareResult{}, fmt.Errorf("share: channel_legacy_id is required")
	}

	var notes []RejectionNote

	protoVis, knownVis := legacyVisibilityToProto[s.Visibility]
	if !knownVis {
		notes = append(notes, RejectionNote{
			LegacyID: s.ChannelLegacyID,
			Reason:   fmt.Sprintf("unknown visibility %q mapped to TEAM", s.Visibility),
			Severity: SeverityWarn,
		})
		protoVis = chsharev1.ShareVisibility_SHARE_VISIBILITY_TEAM
	}

	grants := make([]*ingestv1.MigrateShareRequest_Grant, 0, len(s.Grants))
	for _, g := range s.Grants {
		protoRole, knownRole := legacyRoleToProto[g.Role]
		if !knownRole {
			notes = append(notes, RejectionNote{
				LegacyID: s.ChannelLegacyID,
				Reason:   fmt.Sprintf("unknown grant role %q for user %q mapped to VIEWER", g.Role, g.UserLegacyID),
				Severity: SeverityWarn,
			})
			protoRole = chsharev1.ShareRole_SHARE_ROLE_VIEWER
		}
		grants = append(grants, &ingestv1.MigrateShareRequest_Grant{
			UserLegacyId: g.UserLegacyID,
			Role:         protoRole,
		})
	}

	req := &ingestv1.MigrateShareRequest{
		ChannelLegacyId: s.ChannelLegacyID,
		Visibility:      protoVis,
		Grants:          grants,
	}

	return MapShareResult{Request: req, Notes: notes}, nil
}


