package mapper

import (
	"fmt"

	"google.golang.org/protobuf/types/known/timestamppb"

	ingestv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/dialogue/ingest/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-dialogue/internal/legacy"
)

// MapTagResult carries the mapped request and any soft notes.
type MapTagResult struct {
	Request *ingestv1.MigrateTagRequest
	Notes   []RejectionNote
}

// MapTag translates a LegacyTag into a MigrateTagRequest.
//
// Rules:
//   - conversation_legacy_id is required.
//   - tag is required.
//   - No legacy_id on tags (ON CONFLICT (conversation_id, tag) DO NOTHING handles idempotency).
func MapTag(t legacy.LegacyTag) (MapTagResult, error) {
	if t.ConversationLegacyID == "" {
		return MapTagResult{}, fmt.Errorf("tag %q: conversation_legacy_id is required", t.Tag)
	}
	if t.Tag == "" {
		return MapTagResult{}, fmt.Errorf("tag with conversation %q: tag value is required", t.ConversationLegacyID)
	}

	var taggedAt *timestamppb.Timestamp
	if !t.TaggedAt.IsZero() {
		taggedAt = timestamppb.New(t.TaggedAt)
	}

	req := &ingestv1.MigrateTagRequest{
		ConversationLegacyId: t.ConversationLegacyID,
		Tag:                  t.Tag,
		TaggedByLegacyUserId: t.TaggedByLegacyUserID,
		TaggedAt:             taggedAt,
	}

	return MapTagResult{Request: req}, nil
}


