// TestMapTemplate_HappyPath verifies all fields are set correctly.
func TestMapTemplate_HappyPath(t *testing.T) {
	tmpl := legacy.LegacyTemplate{
		LegacyID:          "tmpl-001",
		Name:              "Welcome Message",
		Category:          "general",
		Content:           "Hello {{name}}, welcome to {{org}}!",
		CreatedByLegacyID: "user-001",
	}
	result, err := mapper.MapTemplate(tmpl)
	require.NoError(t, err)
	require.Empty(t, result.Notes)
	req := result.Request
	assert.Equal(t, "tmpl-001", req.LegacyId)
	assert.Equal(t, "Welcome Message", req.Name)
	assert.Equal(t, templatev1.TemplateCategory_TEMPLATE_CATEGORY_GENERAL, req.Category)
	assert.Equal(t, "Hello {{name}}, welcome to {{org}}!", req.Content)
	assert.Equal(t, "user-001", req.CreatedByLegacyId)
}

